import csv
import io

def _parse_amount(amount_str: str):
    """Convert a formatted amount string to float, handling $ signs, commas,
    and accounting-style parentheses for negatives."""
    s = amount_str.strip()
    if not s:
        return None
    negative = False
    if s.startswith('(') and s.endswith(')'):
        negative = True
        s = s[1:-1]
    s = s.replace('$', '').replace(',', '')
    try:
        value = float(s)
    except ValueError:
        return None
    return -value if negative else value

def summarize_expenses(csv_text: str) -> dict:
    totals = {}
    reader = csv.DictReader(io.StringIO(csv_text))
    for row in reader:
        amount_val = _parse_amount(row.get('amount', ''))
        if amount_val is None:
            continue
        category_raw = row.get('category', '')
        category = category_raw.strip().lower()
        if not category:
            continue
        totals[category] = totals.get(category, 0.0) + amount_val
    return {cat: round(total, 2) for cat, total in totals.items()}


