def summarize_expenses(csv_text: str) -> dict:
    import csv, io
    from decimal import Decimal, ROUND_HALF_UP

    totals = {}
    f = io.StringIO(csv_text)
    reader = csv.reader(f)

    # Skip header row if present
    try:
        next(reader)
    except StopIteration:
        return {}

    for row in reader:
        if not row or len(row) < 3:
            continue

        _, category, amount_str = row[0], row[1], row[2]
        amount_str = amount_str.strip()
        if not amount_str:
            continue

        negative = False
        if amount_str.startswith('(') and amount_str.endswith(')'):
            negative = True
            amount_str = amount_str[1:-1].strip()

        if amount_str.startswith('$'):
            amount_str = amount_str[1:]

        amount_str = amount_str.replace(',', '')

        try:
            amt = Decimal(amount_str)
        except Exception:
            continue

        if negative:
            amt = -amt

        cat_key = category.strip().lower()
        totals[cat_key] = totals.get(cat_key, Decimal('0')) + amt

    result = {}
    for k, v in totals.items():
        rounded = v.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        result[k] = float(rounded)

    return result


