import csv
import io

def summarize_expenses(csv_text: str) -> dict:
    if not csv_text:
        return {}

    # Use StringIO to treat string as file-like object for csv reader
    reader = csv.reader(io.StringIO(csv_text))

    totals = {}

    # Skip header
    try:
        next(reader)
    except StopIteration:
        return {}

    for row in reader:
        # Ensure row has enough columns (date, category, amount)
        if len(row) < 3:
            continue

        category_raw = row[1]
        amount_raw = row[2]

        # Process Category
        if not category_raw:
            continue # Or handle as empty string key? Prompt implies valid categories usually. 
                     # "category names vary..." implies they exist.

        category = category_raw.strip().lower()

        # Process Amount
        if not amount_raw or not amount_raw.strip():
            continue

        amount_str = amount_raw.strip()

        is_negative = False
        if amount_str.startswith('(') and amount_str.endswith(')'):
            is_negative = True
            amount_str = amount_str[1:-1] # Remove parens

        # Remove currency symbols and commas
        # Replace $ with empty, remove ,
        clean_amount_str = amount_str.replace('$', '').replace(',', '')

        try:
            amount = float(clean_amount_str)
        except ValueError:
            continue # If it's not a number, skip

        if is_negative:
            amount = -amount

        totals[category] = totals.get(category, 0.0) + amount

    # Round results
    result = {k: round(v, 2) for k, v in totals.items()}
    return result


