def summarize_expenses(csv_text: str) -> dict:
    reader = csv.reader(io.StringIO(csv_text))
    totals = {}
    first_row = True
    for row in reader:
        # skip empty lines
        if not row or all(cell.strip() == '' for cell in row):
            continue
        # detect and skip header
        if first_row:
            first_row = False
            if len(row) >= 3 and row[0].lower().strip() == 'date' \
               and row[1].lower().strip() == 'category' \
               and row[2].lower().strip() == 'amount':
                continue
        # need at least category and amount
        if len(row) < 3:
            continue
        cat_raw = row[1]
        amt_raw = row[2]
        if cat_raw is None or amt_raw is None:
            continue
        cat = cat_raw.strip().lower()
        if cat == '':
            continue
        amt_str = amt_raw.strip()
        if amt_str == '':
            continue
        # parse amount
        s = amt_str.replace('$', '').replace(',', '')
        if s.startswith('(') and s.endswith(')'):
            inner = s[1:-1]
            try:
                val = -float(inner)
            except ValueError:
                continue
        else:
            try:
                val = float(s)
            except ValueError:
                continue
        totals[cat] = totals.get(cat, 0.0) + val
    # round to 2 decimals
    return {k: round(v, 2) for k, v in totals.items()}


