import re

def error_report(log_text: str) -> list:
    pattern = re.compile(
        r'^(?P<ts>\d{4}-\d{2}-\d{2}T(?P<hour>\d{2}):\d{2}:\d{2})Z '
        r'(?P<level>INFO|WARN|ERROR) .+$'
    )
    counts = {}
    for line in log_text.splitlines():
        m = pattern.match(line.strip())
        if not m:
            continue
        if m.group('level') == 'ERROR':
            hour = m.group('hour')
            counts[hour] = counts.get(hour, 0) + 1
    return [f"{h}: {counts[h]} errors" for h in sorted(counts)]


